"""Generate current tokens and entry documentation from spec.json. --check is read-only."""
from pathlib import Path
import json, sys
root = Path(__file__).resolve().parent
s = json.loads((root / 'spec.json').read_text(encoding='utf-8'))
assets = json.loads((root / 'asset-manifest.json').read_text(encoding='utf-8'))

def legacy_render():
    css = '/* Generated by build_spec.py from spec.json. Do not edit directly. */\n:root {\n' + ''.join(('  ' + k + ':' + v + ';\n' for k, v in s['tokens'].items())) + '}\n'
    for count, vars in s['counts'].items():
        css += ' .scene[data-option-count="' + count + '"]{' + ''.join((k + ':' + v + ';' for k, v in vars.items())) + '}\n'
    layout = '# Current layout: ' + s['version'] + '\n\nAuthoritative inputs: spec.json. Run python build_spec.py to regenerate; python build_spec.py --check detects drift. No historical overrides apply.\n\nScene is16:9 fitted below42px toolbar with8px page padding. Portrait left0/top19%/width30%/height81%; background covers scene. Main panel left24%/top15.5%/width53%/height84.5%, border3 scene cqw. Choose one left28%, top calc(15.5% +3.04cqw), size1.6 scene cqw, line-height1.1; it is below the border in black interior.\n\n'
    for count, overrides in s['counts'].items():
        cfg = {**s['tokens'], **overrides}
        layout += '## ' + count + ' options\n' + '\n'.join(('- ' + k + ': ' + cfg[k] for k in ['--list-left', '--list-top', '--list-width', '--list-gap', '--row-text-top', '--row-text-bottom', '--body-row-size', '--boon-title-size', '--stat-row-size'])) + '\n'
    layout += '\nFont units: body/title/stat tokens are row-container cqw; heading/label/frame units are scene cqw. At1024scene width, all counts retain body≈17.9–18.1px. Three-row width44% is a disclosed adaptation from reference≈46% to reserve entire source canvases and faint glow under the interior label; do not call original composition fidelity approved. Four-row gaps are intentionally tight.\n\nText starts23% of row, right6%. Symbol left2%, width17.2%, square and vertically centered; icon92% within, CSS diamond frame extends3%. Default title line-height1.15/body1.2/stat inherits1.25. Four-row title/body/stat1.1. Description preserves newlines, maximum2lines. There is no reliable universal character limit: at1024 scene width aim for about35–40 ordinary English characters per line, fewer with wide capitals; explicit two-line fixture uses short plain sentences, and recipient normal copy must also be checked. Never truncate data to a character count; genuine overflow is reported and full copy available in dialog, never treated as a fit pass.\n\n'
    layout += '## Raster geometry\n```json\n' + json.dumps({k: s[k] for k in ['row', 'header', 'frame', 'emblem', 'icons']}, indent=2) + '\n```\n'
    layout += 'Normal/selected scale is rowWidth/1893 with source origin25,165. Distinct1942/1945 canvas widths are preserved. All-count alpha>0 bounds must fit panel interior and clear label, including faint nonzero glow. Full transparent canvases are reported; four-row full-canvas containment remains strict from prior harness. Alpha≥32 bounds are supplemental only and do not replace strict nonzero-alpha tests.\n\nHeader uses same unchanged PNG in3CSS slices; x0–450 and1756–2206 endcaps retain scale sceneWidth*.52/2206, central1306px extends horizontally. Overall width77%, left12.5%, top.2%. Canvas aspect169862/37076, upward205/713 shift. Heading source center292.5, line-height1.5; subtitle480, line-height1. Header seams and center weathering elongation remain unverified.\n\nGreek frame uses border-image slices190/155/180/155, round edges. Tooltip left76%/top66%/width23%/height18%; full text in modal if clipped. Medallion is independent of portrait.\n'
    assetdoc = '# Required binaries\n\nNo binaries are inside the code ZIP.10PNGs and7TTFs are required. Do not overwrite older versioned assets.\n\n' + '\n'.join(('- ' + a['path'] + ' | ' + str(a['bytes']) + ' bytes | SHA256 ' + a['sha256'] for a in assets['pngs'] + assets['fonts'])) + '\n\nPNG dimensions and alpha bounds are in spec.json and LAYOUT.md. No original screenshot assets are redistributed.\n'
    usage = '## Input/output and usage\n1. Decode this code ZIP, extract it to a new folder. Supply exact binaries listed in asset-manifest.json; copy unchanged fonts and their three OFL licenses into fonts/. Run python verify_assets.py.\n2. Open scene.html for scene; prototype.html is the separate editor. No server or network dependency. index.html is overview.\n3. Editor changes stay only in that page memory. Edit screen title/subtitle, choose an option, edit name, relative icon path, description, stat or Rare/Epic. Add/remove stays between2and4.\n4. Click Export JSON to download; open scene.html and Import JSON via file picker. Reload resets to data.js unless re-imported. There is no automatic storage or cross-page synchronization.\n5. Runtime input is window.HADES_DRAFT in data.js or imported JSON. HadesDataIO.validate(input) returns normalized schemaVersion1/version/title/subtitle/options without mutating input. HadesDataIO.nextIndex(index,key,count) returns dynamic navigation index. readFile(file) validates up to512KiB; download(data) exports hades-scene-data.json.\n6. Input must have2–4objects in options, nonempty string title at scene and option levels, string subtitle/description/stat (empty permitted), rarity exactly Rare or Epic, icon matching components/[a-z0-9][a-z0-9_-]*.png. Paths/URLs/traversal/glyph substitutes are rejected. Unknown fields discarded; strings rendered with textContent. Explicit option values survive translated labels. HTML requests translate=no; browser opt-out is advisory.\n\nExample input (two options):\n```json\n{"schemaVersion":1,"title":"BOONS OF HERMES","subtitle":"Choose your boon","options":[{"title":"Greater Haste","rarity":"Rare","description":"You move faster.\\nGain bonus speed.","stat":"+30%","icon":"components/icon-haste-ref.png"},{"title":"Greater Evasion","rarity":"Epic","description":"You can dodge attacks.","stat":"+15%","icon":"components/icon-evasion-ref.png"}]}\n```\nOutput: same validated fields plus current version; options count preserved. Duplicate the first option for3/4 examples, edit its text/icon, and import. Sample data.js remains3 options. No add/remove occurs inside gameplay scene; use editor or JSON.\n\n## States, input and accessibility\nNormal row is restrained gray. Rare blue/Epic purple wedge is independent CSS. Only selected row shows yellowgreen PNG overlay. Mouse click selects; Arrow keys wrap; Home/End choose first/last; Enter confirms status in scene or opens editor details. Selected row alone is tabbable. Modal moves focus to Close, traps Tab, Escape closes and restores trigger focus; surrounding regions inert. Overflow measurements run after fonts/load/resize/input. Nothing is hidden merely to satisfy tests.\n\n## Fonts and provenance\nSpectralSC-Regular: heading. AlegreyaSansSC-Regular: boon/rarity. AlegreyaSans-Regular: body; Bold:stat; Italic:flavor. AlegreyaSansSC-Bold:controls/tooltip. SpectralSC-Bold available. Files fetched unchanged from google/fonts OFL directories; retain all three OFL1.1 licenses. Exact game-font versions are not established. Fonts are locally loaded, no CDN. Official sources: https://github.com/google/fonts/tree/main/ofl/spectralsc and https://github.com/google/fonts/tree/main/ofl/alegreyasans and https://github.com/google/fonts/tree/main/ofl/alegreyasanssc .\n'
    qa = '# v2.10 evidence and limits\nStatus: draft, not approved. R06 single-current-spec documentation generated from spec.json; consistency test checks exact generated files and critical CSS contract. Browser regressions not run here.\n\nRecipient v2.7 evidence only: exact code SHA/48manifest/17binary hashes, real render; medallion/frame/icon density improved; title42/42 with no warning; four-option normal two-line content78/78 with complete stat. Default3 failed: client78/scroll81, stat overflow~2.93px. Choose one overlapped Greek-key border: outertop139.90, border31, inner170.90, label142.82–170.91. These passes do not transfer automatically to v2.10.\n\nv2.10 adjusts all-count content room, interior label and layout spacing while retaining text pixel sizes. Full-canvas plus measured painted-bound checks remain. Four-row gaps are tighter; three-row width changes to44%, a known composition tradeoff. Actual browser screenshots must decide readability and alignment. Reference fidelity, seams, animation and independent third-screen reproduction remain open.\n\nRun node tests/data-io.test.cjs for pure data; python build_spec.py --check for document/token consistency; python tests/spec_consistency.py for code/spec contract. Run node tests/option-counts.cjs /absolute/package/root /absolute/output only in approved Playwright environment after assembly. It covers2/3/4, two-line copy+stat, full canvases inside panel, label inside black interior/above artwork, header, input and export; screenshots require human review. Portable-flow and scene-smoke are supplemental. No browser launch attempted here.\n\nOriginal references are evidence-only, outside customer package. Public reference URLs:\n' + '\n'.join(s['sources']) + '\nEarly-access reference build differs from2020final; exact build of Gamepressure screenshot unknown. No commercial rights clearance claimed.\n'
    readme = '# Hades v2.10 draft\n\nStart with ASSEMBLE.md, then scene.html. All binaries unchanged from v2.7; no new images. This code-only package does not need an older code ZIP.\n\n' + usage + '\nSee LAYOUT.md for exact current geometry, QA.md for evidence/limits, RIGHTS.md for caveats. Historical rules live only in CHANGELOG.md.\n'
    runtime_rules = ['2–4 options use independent images, editable text and state layers.', 'Current normal row: ' + s['row']['normal'] + '; canvas ' + str(s['row']['normalCanvas']) + '; alpha>=32 bounds ' + str(s['row']['normalAlpha32']) + '.', 'Current selected overlay: ' + s['row']['selection'] + '; canvas ' + str(s['row']['selectionCanvas']) + '; alpha>=32 bounds ' + str(s['row']['selectionAlpha32']) + '.', 'Both preserve native proportions at rowWidth/' + str(s['row']['core'][0]) + ' scale, with shared source origin ' + str(s['row']['origin']) + '. Source PNG bytes are unchanged.', 'Strict glow tests use full nonzero-alpha bounds, not the alpha>=32 threshold. See current LAYOUT.md for layout and transparent-canvas limits.', 'Clipping is measured after fonts load, resize and edits. Full text stays available here; warnings are not a visual-acceptance pass.', 'Rare/Epic wedges and selected artwork are independent. Source fidelity and this version browser regression remain pending.']
    return {'runtime-spec.js': 'window.HADES_RUNTIME_RULES = ' + json.dumps(runtime_rules, ensure_ascii=False, indent=2) + ';\n', 'tokens.css': css, 'LAYOUT.md': layout, 'SKILL.md': '# Hades customer implementation Skill, v2.10\n\n' + usage + '\n' + layout, 'RULES.md': '# Current rules\n\nUse spec.json as source of truth.2–4 options; default3. Never flatten editable text or substitute source screenshot crops. Preserve source PNG dimensions and slice coordinates. Keep Rare/Epic machine values explicit. Generate tokens/docs together. All acceptance statuses remain independent of implementation claims.\n\n' + layout, 'README.md': readme, 'components/README.md': assetdoc, 'ASSEMBLE.md': '# Assemble v2.10\n\n' + usage.split('## States')[0] + '\n' + assetdoc, 'QA.md': qa}
def render():
    sys.path.insert(0,str(root))
    import customer_docs
    return customer_docs.render(legacy_render(),s,assets,root)

if __name__ == '__main__':
    bad = []
    for name, text in render().items():
        p = root / name
        if '--check' in sys.argv:
            if not p.exists() or p.read_text(encoding='utf-8') != text:
                bad.append(name)
        else:
            p.parent.mkdir(exist_ok=True)
            p.write_text(text, encoding='utf-8')
    if bad:
        raise SystemExit('DRIFT: ' + ', '.join(bad))
    print('Current spec documents/tokens consistent' if '--check' in sys.argv else 'Generated current specification')
